+	t.Parallel()
+	terminal, input, err := pty.Open()
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { _ = terminal.Close() })
+	t.Cleanup(func() { _ = input.Close() })
